// The Error Trigger payload has "execution" for normal failures and "trigger"
// when the trigger node itself failed. Only metadata is stored: input data can
// contain personal or secret values, so it is deliberately not copied here.
const e = $json;
const execution = e.execution ?? {};
const trigger = e.trigger ?? {};
const err = execution.error ?? trigger.error ?? {};
const message = String(err.message ?? 'unknown error').slice(0, 2000);

// Coarse classification. Tune the patterns to the errors your workflows produce.
const text = `${message} ${err.description ?? ''}`.toLowerCase();
let errorClass = 'unknown';
if (/timeout|timed out|econnreset|econnrefused|socket hang up|\b50[234]\b|\b429\b|rate limit/.test(text)) errorClass = 'transient';
else if (/\b40[0134]\b|\b422\b|validation|invalid|not found|unauthorized|forbidden/.test(text)) errorClass = 'permanent';

return [{
  json: {
    source_workflow: e.workflow?.name ?? 'unknown workflow',
    source_node: execution.lastNodeExecuted ?? trigger.node?.name ?? null,
    execution_id: execution.id ? String(execution.id) : null,
    error_message: message,
    error_class: errorClass,
    context: {
      workflow_id: e.workflow?.id ?? null,
      mode: execution.mode ?? trigger.mode ?? null,
      execution_url: execution.url ?? null,
      retry_of: execution.retryOf ?? null,
      trigger_failed: Boolean(e.trigger),
    },
  },
}];
